package com.vit.sales.ui;
import com.vit.sales.db.DatabaseManager;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;
public final class ReportsPanel extends JPanel{private final DatabaseManager db;private final JComboBox<String> report=new JComboBox<>(new String[]{"Sales by month","Top customers","Best-selling products","Low stock","Order/payment reconciliation"});private final JTable table=new JTable();private final JLabel summary=new JLabel("Select a report and click Run.");public ReportsPanel(DatabaseManager db){this.db=db;setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(16,16,16,16));JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT));top.add(report);JButton run=new JButton("Run report");run.addActionListener(e->load());top.add(run);add(top,BorderLayout.NORTH);table.setAutoCreateRowSorter(true);add(new JScrollPane(table),BorderLayout.CENTER);add(summary,BorderLayout.SOUTH);}
private void load(){String sql=switch((String)report.getSelectedItem()){case "Sales by month"->"SELECT DATE_FORMAT(o.order_date,'%Y-%m') month,COUNT(DISTINCT o.order_id) orders,COALESCE(SUM(d.quantity*d.unit_price),0) sales FROM Orders o LEFT JOIN Order_Details d ON d.order_id=o.order_id WHERE o.order_status<>'Cancelled' GROUP BY DATE_FORMAT(o.order_date,'%Y-%m') ORDER BY month";case "Top customers"->"SELECT c.customer_id,c.customer_name,COUNT(DISTINCT o.order_id) orders,COALESCE(SUM(d.quantity*d.unit_price),0) total_spend FROM Customer c LEFT JOIN Orders o ON o.customer_id=c.customer_id AND o.order_status<>'Cancelled' LEFT JOIN Order_Details d ON d.order_id=o.order_id GROUP BY c.customer_id,c.customer_name ORDER BY total_spend DESC";case "Best-selling products"->"SELECT p.product_id,p.product_name,COALESCE(SUM(CASE WHEN o.order_status<>'Cancelled' THEN d.quantity ELSE 0 END),0) units_sold,COALESCE(SUM(CASE WHEN o.order_status<>'Cancelled' THEN d.quantity*d.unit_price ELSE 0 END),0) sales FROM Product p LEFT JOIN Order_Details d ON d.product_id=p.product_id LEFT JOIN Orders o ON o.order_id=d.order_id GROUP BY p.product_id,p.product_name ORDER BY units_sold DESC";case "Low stock"->"SELECT product_id,product_name,stock_quantity,price FROM Product WHERE stock_quantity<=10 ORDER BY stock_quantity";default->"SELECT o.order_id,o.order_status,COALESCE(SUM(d.quantity*d.unit_price),0) order_total,p.amount payment_amount,(COALESCE(SUM(d.quantity*d.unit_price),0)-COALESCE(p.amount,0)) difference FROM Orders o LEFT JOIN Order_Details d ON d.order_id=o.order_id LEFT JOIN Payment p ON p.order_id=o.order_id GROUP BY o.order_id,o.order_status,p.amount ORDER BY o.order_id";};try(Connection c=db.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){DefaultTableModel m=new DefaultTableModel();ResultSetMetaData d=r.getMetaData();for(int i=1;i<=d.getColumnCount();i++)m.addColumn(d.getColumnLabel(i));int rows=0;while(r.next()){Object[] a=new Object[d.getColumnCount()];for(int i=1;i<=a.length;i++)a[i-1]=r.getObject(i);m.addRow(a);rows++;}table.setModel(m);summary.setText("Rows: "+rows+" | Report is read-only.");}catch(SQLException e){JOptionPane.showMessageDialog(this,e.getMessage(),"Report failed",JOptionPane.ERROR_MESSAGE);}}}
